using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // EF Core 9 breaking change: Migrate() inside a manual transaction now throws.
    // Fix: call Migrate() outside BeginTransaction(); it manages its own transactions.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }

    // EF Core 9 breaking change: Cosmos DB provider removed synchronous I/O support.
    // Sync calls like .ToList() on Cosmos queries now throw InvalidOperationException.
    // Fix: use async methods throughout.
    async Task QueryCosmosAsync(CosmosDbContext cosmosDb)
    {
        // BEFORE (broken in EF Core 9):
        //   var products = cosmosDb.Products.Where(p => p.Category == "Toys").ToList();

        // AFTER (required in EF Core 9):
        var products = await cosmosDb.Products
            .Where(p => p.Category == "Toys")
            .ToListAsync();
    }
}

